do
    local function grades(t)
        if type(t) ~= 'table' or t[1] ~= nil or t[2] ~= nil or t[3] ~= nil then return t end
        return { t.poor, t.good, t.perfect }
    end
    for _, row in ipairs(CampAnimals or {}) do
        row.price = grades(row.price)
        row.quality = grades(row.quality)
    end
end
